import React, { PropsWithChildren, useLayoutEffect, useRef } from 'react';

import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import { uuidv4 } from '../../../core/utils/uuidv4.js';
import { useThrottledResizeObserver } from '../../core/hooks/useThrottledResizeObserver.js';
import { useGlobalFontSize } from '../../single-value-grid/hooks/use-global-font-size.js';
import { FONT_HEIGHT_RATIO, FONT_WIDTH_RATIO } from '../constants.js';
import { FontSizeContext } from '../contexts/font-size.context.js';
import { useFontSizeForContainer } from '../hooks/use-font-size-for-container.js';

/**
 * Given a text, it will provide a refCallback to observe the size of a container element, to give the proper fontSize to the text
 *
 * @param text - value text
 * @param suffix - unit text
 * @param children -
 */
export const FontSizeProvider = ({
  text,
  suffix,
  children,
}: PropsWithChildren<{
  text: string;
  suffix?: string;
}>) => {
  const ref = useRef<HTMLDivElement>();

  const { refCallback, width = 0, height = 0 } = useThrottledResizeObserver();

  const mergedRef = useMergeRefs([refCallback, ref]);

  const preferredFontSize = useFontSizeForContainer({
    container: {
      width: width * FONT_WIDTH_RATIO,
      height: height * FONT_HEIGHT_RATIO,
    },
    text,
    element: ref.current?.querySelector('span') as HTMLElement, // element containing text font style
    suffix,
    suffixElement: ref.current?.querySelector('small') as HTMLElement, // element containing suffix font style
  });

  const id = useRef<string>(uuidv4());
  const { updateValueFontSize } = useGlobalFontSize();

  useLayoutEffect(() => {
    if (height && width) {
      updateValueFontSize?.(id.current, preferredFontSize);
    }
  }, [height, width, preferredFontSize]);

  return (
    <FontSizeContext.Provider
      value={{
        fontSize: preferredFontSize,
        refCallback: mergedRef,
      }}
    >
      {children}
    </FontSizeContext.Provider>
  );
};
